func _tick_resident(slot: int) -> StringName:
	"""Integrate one resident: sample health inputs, then needs, cold, health, status.

	The health inputs are sampled BEFORE the needs move, so a tick's health effect reflects
	the state the resident was actually in during that tick. This is winter_world.gd's own
	ordering (it reads `starving` before decaying hunger) and is kept deliberately.
	"""
	var starving: bool = _need_value[slot * NEED_COUNT + NEED_HUNGER] == HUNGER_STARVING_VALUE
	var cold_gain: int = _cold_gain_milli_per_hour(slot)
	var health_rate: int = _health_rate_per_hour(slot, starving, cold_gain)
	var cold_rate: int = _cold_rate_milli_per_hour(slot, cold_gain)
	_fill_need_rates(slot)
	var code: StringName = _integrate_needs(slot)
	if code != REFUSE_NONE:
		return code
	code = _integrate_cold(slot, cold_rate)
	if code != REFUSE_NONE:
		return code
	code = _integrate_health(slot, health_rate)
	if code != REFUSE_NONE:
		return code
	if starving:
		_starving_ticks[slot] += 1
	_refresh_status(slot)
	return REFUSE_NONE


func _integrate_needs(slot: int) -> StringName:
	"""Integrate all five needs of one resident for one tick from `_rate_scratch`."""
	for need: int in NEED_COUNT:
		var index: int = slot * NEED_COUNT + need
		var code: StringName = _integrate_step(_need_value[index], _need_remainder[index],
			_rate_scratch[need], NEED_DENOMINATOR, NEED_MIN, NEED_MAX)
		if code != REFUSE_NONE:
			return code
		_need_value[index] = _step_value
		_need_remainder[index] = _step_remainder
	return REFUSE_NONE


func _integrate_cold(slot: int, rate: int) -> StringName:
	"""Integrate cold exposure in milli-hours for one tick, floored at 0.

	There is no upper bound in the specification, so the only ceiling is int64 itself and
	_integrate_step() refuses rather than wrapping if a caller ever drives it that far.
	"""
	var code: StringName = _integrate_step(_cold_milli_hours[slot], _cold_remainder[slot],
		rate, COLD_DENOMINATOR, 0, IntMath.INT64_MAX)
	if code != REFUSE_NONE:
		return code
	_cold_milli_hours[slot] = _step_value
	_cold_remainder[slot] = _step_remainder
	return REFUSE_NONE


func _integrate_health(slot: int, rate: int) -> StringName:
	"""Integrate health for one tick and record a death when it reaches 0 (REQ-SET-016)."""
	var code: StringName = _integrate_step(_health[slot], _health_remainder[slot],
		rate, HEALTH_DENOMINATOR, HEALTH_MIN, HEALTH_MAX)
	if code != REFUSE_NONE:
		return code
	var died: bool = _step_value == HEALTH_MIN and _health[slot] > HEALTH_MIN
	_health[slot] = _step_value
	_health_remainder[slot] = _step_remainder
	if died:
		_death_count += 1

func apply_incident(slot: int, kind: int, severity: int, immediate_health_loss: int,
		incident_ordinal: int, needs: Needs) -> Needs.OpResult:
	"""Apply one injury incident: its one-shot health loss, then the aggregate merge.

	`incident_ordinal` is the caller's per-resident event ordinal and must strictly exceed the
	last one applied, so a replayed §5.4 hazard roll or a retried job commit refuses instead of
	charging its damage twice (HAZ-004). Returns the signed health the resident absorbed, which
	is 0 for an incident whose specified immediate loss is 0.
	"""
	return _result(_apply_incident_checked(slot, kind, severity, immediate_health_loss,
		incident_ordinal, needs))


func _apply_incident_checked(slot: int, kind: int, severity: int, loss: int,
		ordinal: int, needs: Needs) -> StringName:
	"""Validate everything, charge the health loss, then merge. Refuses before writing.

	ORDERING IS THE DEATH GUARANTEE. `needs.apply_health_event()` is the only step that can
	fail, and it validates before it writes, so a refusal leaves both stores byte-identical.
	It runs BEFORE this store is touched; a lethal loss therefore commits the death first and
	every later call on this row -- treatment included -- meets a dead resident and refuses.
	"""
	var code: StringName = _check_incident_arguments(slot, kind, severity, loss, ordinal, needs)
	if code != REFUSE_NONE:
		return code
	var health: Needs.OpResult = needs.apply_health_event(slot, -loss)
	if not health.ok:
		return REFUSE_NEEDS_REFUSED
	if _kind[slot] == KIND_NONE:
		_injured_count += 1
	_merge_aggregate(slot, kind, severity)
	_last_incident_ordinal[slot] = ordinal
	_out_value = health.value
	return _publish_injury_state(slot, needs)


func _check_incident_arguments(slot: int, kind: int, severity: int, loss: int,
		ordinal: int, needs: Needs) -> StringName:
	"""Every precondition of one incident, checked before any column is written."""
	var code: StringName = _check_live_slot(slot, needs)
	if code != REFUSE_NONE:
		return code
	if kind <= KIND_NONE or kind >= KIND_COUNT:
		return REFUSE_INVALID_KIND
	if severity != SEVERITY_MINOR and severity != SEVERITY_SERIOUS:
		return REFUSE_INVALID_SEVERITY
	if loss < 0 or loss > Needs.HEALTH_MAX:
		return REFUSE_INVALID_HEALTH_LOSS
	if ordinal <= 0:
		return REFUSE_INVALID_ORDINAL
	if ordinal <= _last_incident_ordinal[slot]:
		return REFUSE_DUPLICATE_INCIDENT
	return REFUSE_NONE


func _merge_aggregate(slot: int, kind: int, severity: int) -> void:
	"""GDD §4.2 / HAZ-004 merge: worse severity replaces, ties keep the lower InjuryKind ID.

	`untreated_ticks` and `care_progress_mwu` are untouched on purpose: HAZ-004 states that a
	new incident erases neither elapsed untreated time nor already paid care work.
	"""
	if _kind[slot] == KIND_NONE or severity > _severity[slot]:
		_kind[slot] = kind
		_severity[slot] = severity
		return
	if severity == _severity[slot] and kind < _kind[slot]:
		_kind[slot] = kind

